#include <bits/stdc++.h>
using namespace std;
int main(){string line;cout<<"Enter production (example A->Aa|Ab|c|d): ";cin>>line;auto k=line.find("->");if(k==string::npos)return 1;string A=line.substr(0,k),rhs=line.substr(k+2);vector<string> alpha,beta;stringstream ss(rhs);string x;while(getline(ss,x,'|')){if(x.rfind(A,0)==0)alpha.push_back(x.substr(A.size()));else beta.push_back(x);}if(alpha.empty()){cout<<"No immediate left recursion\n";return 0;}if(beta.empty()){cout<<"Cannot apply standard transformation: no non-left-recursive alternative\n";return 0;}cout<<A<<" -> ";for(size_t i=0;i<beta.size();i++){if(i)cout<<" | ";cout<<(beta[i]=="#"?"":beta[i])<<A<<"'";}cout<<"\n"<<A<<"' -> ";for(size_t i=0;i<alpha.size();i++){if(i)cout<<" | ";cout<<alpha[i]<<A<<"'";}cout<<" | #\n";}
